  1	function exp(b: nat, n: nat): nat {
  2	  if n == 0 then 1
  3	  else b * exp(b, n-1)
  4	}
  5	
  6	lemma exp_sum(b: nat, n1: nat, n2: nat)
  7	  ensures exp(b, n1 + n2) == exp(b, n1) * exp(b, n2)
  8	{
  9	  if n1 == 0 {
 10	    return;
 11	  } else {
 12	    exp_sum(b, n1-1, n2);
 13	  }
 14	}
 15	
 16	lemma exp_sum_auto(b: nat)
 17	  ensures forall n1: nat, n2: nat :: exp(b, n1 + n2) == exp(b, n1) * exp(b, n2)
 18	{
 19	  forall n1: nat, n2: nat
 20	    ensures exp(b, n1 + n2) == exp(b, n1) * exp(b, n2) {
 21	    exp_sum(b, n1, n2);
 22	  }
 23	}
 24	
 25	function bits(n: nat): seq<bool>
 26	  decreases n
 27	{
 28	  if n == 0 then []
 29	  else [if (n % 2 == 0) then false else true] + bits(n/2)
 30	}
 31	
 32	function from_bits(s: seq<bool>): nat {
 33	  if s == [] then 0
 34	  else (if s[0] then 1 else 0) + 2 * from_bits(s[1..])
 35	}
 36	
 37	lemma bits_from_bits(n: nat)
 38	  ensures from_bits(bits(n)) == n
 39	{
 40	}
 41	
 42	lemma bits_trim_front(n: nat)
 43	  requires n > -1
 44	  ensures from_bits(bits(n)[1..]) == n/2
 45	{}
 46	
 47	lemma from_bits_append(s: seq<bool>, b: bool)
 48	  ensures from_bits(s + [b]) == from_bits(s) + exp(2, |s|) * (if b then 1 else 0)
 49	{
 50	  if s == [] {
 51	    return;
 52	  }
 53	  assert s == [s[0]] + s[1..];
 54	  from_bits_append(s[1..], b);
 55	  // from recursive call
 56	  assert from_bits(s[1..] + [b]) == from_bits(s[1..]) + exp(2, |s|-1) * (if b then 1 else 0);
 57	  exp_sum(2, |s|-1, 1);
 58	  assert (s + [b])[1..] == s[1..] + [b]; // observe
 59	  assert from_bits(s + [b]) == (if s[0] then 1 else 0) + 2 * from_bits(s[1..] + [b]);
 60	}
 61	
 62	lemma from_bits_sum(s1: seq<bool>, s2: seq<bool>)
 63	  decreases s2
 64	  ensures from_bits(s1 + s2) == from_bits(s1) + exp(2, |s1|) * from_bits(s2)
 65	{
 66	  if s2 == [] {
 67	    assert s1 + s2 == s1;
 68	    return;
 69	  }
 70	  from_bits_sum(s1 + [s2[0]], s2[1..]);
 71	  assert s1 + [s2[0]] + s2[1..] == s1 + s2;
 72	  from_bits_append(s1, s2[0]);
 73	  assume false; // TODO
 74	}
