 76	method fast_exp(b: nat, n: nat) returns (r: nat)
 77	  ensures r == exp(b, n)
 78	{
 79	  var a := 1;
 80	  var c := b;
 81	  ghost var n0 := n;
 82	  var n := n;
 83	  ghost var i: nat := 0;
 84	  bits_from_bits(n);
 85	  while n > 0
 86	    decreases n
 87	    invariant c == exp(b, exp(2, i))
 88	    invariant n <= n0
 89	    invariant i <= |bits(n0)|
 90	    invariant bits(n) == bits(n0)[i..]
 91	    invariant n == from_bits(bits(n0)[i..])
 92	    invariant a == exp(b, from_bits(bits(n0)[..i]))
 93	  {
 94	    ghost var n_loop_top := n;
 95	    if n % 2 == 1 {
 96	      assert bits(n)[0] == true;
 97	      // a accumulates sum(i => b^(2^n_i), i) where n_i are the 1 bits of n
 98	      // TODO: n0-n is sum(i => 2^n_i, i), right?
 99	      a := a * c;
100	      exp_sum(b, n0-n, i);
101	      // (n-1)/2 == n/2 in this case, but we want to be extra clear that we're
102	      // "dropping" a 1 bit here and so something interesting is happening
103	      n := (n-1) / 2;
104	      assert 2 * exp(2, i) == exp(2, i+1);
105	      assert a == exp(b, from_bits(bits(n0)[..i]) + exp(2, i)) by {
106	        exp_sum_auto(b);
107	      }
108	      assume false;
109	      assert a == exp(b, from_bits(bits(n0)[..i+1]));
110	    } else {
111	      assert bits(n)[0] == false;
112	      n := n / 2;
113	      assume false;
114	      assert a == exp(b, from_bits(bits(n0)[..i+1]));
115	    }
116	    assert n == n_loop_top/2;
117	    c := c * c;
118	    exp_sum(b, exp(2, i), exp(2, i));
119	    // assert bits(n0)[i+1..] == bits(n0)[i..][1..];
120	    i := i + 1;
121	  }
122	  assert bits(n0)[..i] == bits(n0);
123	  return a;
124	}
